```go
package kindergarten

import (
	"errors"
	"fmt"
	"sort"
	"strings"
)

// plantNames maps the single-letter cup codes to plant names.
var plantNames = map[rune]string{
	'G': "grass",
	'C': "clover",
	'R': "radishes",
	'V': "violets",
}

// Garden holds the plant diagram and the ordered list of children.
type Garden struct {
	rows     [2]string
	children []string // sorted alphabetically; a copy of the argument
}

// NewGarden validates the diagram and children and returns a Garden.
//
// The diagram argument starts each row with a '\n' so that raw string
// literals can present the two rows flush left.
func NewGarden(diagram string, children []string) (*Garden, error) {
	if !strings.HasPrefix(diagram, "\n") {
		return nil, errors.New("diagram must start with a newline")
	}
	rows := strings.Split(strings.TrimPrefix(diagram, "\n"), "\n")
	if len(rows) != 2 {
		return nil, errors.New("diagram must have exactly two rows")
	}
	if len(rows[0]) != len(rows[1]) {
		return nil, errors.New("diagram rows must be the same length")
	}
	if len(rows[0])%2 != 0 {
		return nil, errors.New("diagram rows must have an even number of cups")
	}
	for _, row := range rows {
