// plantNames maps the single-letter cup codes to plant names.
var plantNames = map[rune]string{
	'G': "grass",
	'C': "clover",
	'R': "radishes",
	'V': "violets",
}

// Garden holds the two diagram rows and the alphabetically ordered
// list of children. Each Garden is self-contained; the children
// slice is a copy of the argument and is never modified in place.
type Garden struct {
	rows     [2]string
	children []string // sorted alphabetically
}

// NewGarden validates the diagram and the list of children and
// returns a Garden.
//
// The diagram argument starts each row with a '\n'.  This allows Go's
// raw string literals to present diagrams in source code nicely as two
// rows flush left, for example,
//
//	diagram := `
//	VVCCGG
//	VVCCGG`
func NewGarden(diagram string, children []string) (*Garden, error) {
	if !strings.HasPrefix(diagram, "\n") {
		return nil, errors.New("diagram must start with a newline")
	}
	rows := strings.Split(strings.TrimPrefix(diagram, "\n"), "\n")
	if len(rows) != 2 {
		return nil, errors.New("diagram must have exactly two rows")
	}
	if len(rows[0]) != len(rows[1]) {
		return nil, errors.New("diagram rows must be the same length")
	}
	if len(rows[0])%2 != 0 {
		return nil, errors.New("diagram rows must have an even number of cups")
	}
	for _, row := range rows {
		for _, c := range row {
			if _, ok := plantNames[c]; !ok {
				return nil, fmt.Errorf("invalid cup code %q", c)
			}
		}
	}
	if len(children) == 0 {
		return nil, errors.New("no children")
	}
	seen := make(map[string]bool, len(children))
	for _, c := range children {
		if c == "" {
			return nil, errors.New("empty child name")
		}
		if seen[c] {
			return nil, fmt.Errorf("duplicate child name %q", c)
		}
		seen[c] = true
	}
	if 2*len(children) > len(rows[0]) {
		return nil, errors.New("not enough cups for all children")
	}
	sorted := make([]string, len(children))
	copy(sorted, children)
	sort.Strings(sorted)
	return &Garden{rows: [2]string{rows[0], rows[1]}, children: sorted}, nil
}

// Plants returns the four plants belonging to child, in the order:
// first row left cup, first row right cup, second row left cup,
// second row right cup. ok is false if child is not in the garden.
func (g *Garden) Plants(child string) ([]string, bool) {
	i := sort.SearchStrings(g.children, child)
	if i >= len(g.children) || g.children[i] != child {
		return nil, false
	}
	plants := make([]string, 0, 4)
	for _, row := range g.rows {
		plants = append(plants, plantNames[row[2*i]], plantNames[row[2*i+1]])
	}
